//! Golden-corpus tests against the original JS evaluator.
//!
//! The corpora are generated by oracle/golden-eval.js from
//! js/probability-core.js, the authoritative evaluator in v1.5.8 (verified
//! exhaustively against the other JS evaluators, see
//! tests/golden/eval/evaluator-equivalence.json).

use std::path::PathBuf;

use poker_core::{Card, Deck, MAX_EVALUATED_CARDS, Variant, evaluate};
use serde::Deserialize;

#[derive(Debug, Deserialize)]
struct EvalCase {
    cards: Vec<String>,
    rank: u8,
    score: u64,
    name: String,
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct ExhaustiveHash {
    variant: String,
    cards_per_hand: u8,
    combinations: u64,
    score_hash: String,
    rank_histogram: Vec<u64>,
}

fn golden_dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
        .join("..")
        .join("..")
        .join("tests")
        .join("golden")
        .join("eval")
}

fn read_jsonl<T: for<'de> Deserialize<'de>>(path: &PathBuf) -> Vec<T> {
    let text = std::fs::read_to_string(path)
        .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
    text.lines()
        .filter(|line| !line.trim().is_empty())
        .map(|line| {
            serde_json::from_str(line)
                .unwrap_or_else(|error| panic!("bad golden line: {error}\n{line}"))
        })
        .collect()
}

#[test]
fn js_golden_evaluation_cases_match() {
    for (variant, file_name) in [
        (Variant::Standard, "standard-cases.jsonl"),
        (Variant::ShortDeck, "shortdeck-cases.jsonl"),
    ] {
        let mut path = golden_dir();
        path.push(file_name);
        let cases: Vec<EvalCase> = read_jsonl(&path);
        assert!(
            cases.len() > 7000,
            "corpus {} too small: {}",
            file_name,
            cases.len()
        );
        for case in &cases {
            let cards: Vec<Card> = case
                .cards
                .iter()
                .map(|text| {
                    text.parse()
                        .unwrap_or_else(|error| panic!("bad card {text}: {error}"))
                })
                .collect();
            assert!(cards.len() <= MAX_EVALUATED_CARDS);
            let got = evaluate(&cards, variant);
            assert_eq!(
                got.rank_index(),
                case.rank,
                "rank mismatch for {:?} ({variant:?})",
                case.cards
            );
            assert_eq!(
                got.score(),
                case.score,
                "score mismatch for {:?} ({variant:?})",
                case.cards
            );
            assert_eq!(
                got.name(),
                case.name,
                "name mismatch for {:?} ({variant:?})",
                case.cards
            );
        }
    }
}

const FNV_OFFSET: u64 = 14_695_981_039_346_656_037;
const FNV_PRIME: u64 = 1_099_511_628_211;

#[test]
fn five_card_exhaustive_hash_matches_js() {
    for (variant, file_name) in [
        (Variant::Standard, "standard-five-card-hash.json"),
        (Variant::ShortDeck, "shortdeck-five-card-hash.json"),
    ] {
        let mut path = golden_dir();
        path.push(file_name);
        let text = std::fs::read_to_string(&path)
            .unwrap_or_else(|error| panic!("cannot read {}: {error}", path.display()));
        let meta: ExhaustiveHash = serde_json::from_str(&text).expect("hash metadata");
        assert_eq!(meta.cards_per_hand, 5);
        assert_eq!(
            meta.variant,
            if variant.is_short_deck() {
                "shortdeck"
            } else {
                "standard"
            }
        );

        let deck = Deck::new(variant);
        let cards = deck.cards();
        let n = cards.len();
        let mut hash = FNV_OFFSET;
        let mut histogram = [0u64; 10];
        let mut combinations = 0u64;
        for a in 0..n - 4 {
            for b in a + 1..n - 3 {
                for c in b + 1..n - 2 {
                    for d in c + 1..n - 1 {
                        for e in d + 1..n {
                            let hand = [cards[a], cards[b], cards[c], cards[d], cards[e]];
                            let evaluated = evaluate(&hand, variant);
                            hash ^= u64::from(evaluated.rank_index());
                            hash = hash.wrapping_mul(FNV_PRIME);
                            hash ^= evaluated.score();
                            hash = hash.wrapping_mul(FNV_PRIME);
                            histogram[usize::from(evaluated.rank_index())] += 1;
                            combinations += 1;
                        }
                    }
                }
            }
        }
        assert_eq!(combinations, meta.combinations);
        assert_eq!(hash, meta.score_hash.parse::<u64>().expect("hash"));
        assert_eq!(histogram.to_vec(), meta.rank_histogram);
    }
}
